def main():
    print("=" * 70)
    print("🚀 BẮT ĐẦU NẠP ĐỢT 2: 235 CÂU HỎI MỚI VÀO CƠ SỞ DỮ LIỆU")
    print("=" * 70)

    # 1. Nạp và bổ sung vào categories/*.json
    total_added = 0
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()

    for cat_name, questions in BATCH_2_QUESTIONS.items():
        cat_file = os.path.join(CATEGORIES_DIR, f"{cat_name}.json")
        existing_list = []
        if os.path.exists(cat_file):
            try:
                with open(cat_file, 'r', encoding='utf-8') as f:
                    existing_list = json.load(f)
            except Exception as e:
                print(f"Lỗi đọc file {cat_name}.json: {e}")

        # Chuẩn hóa để chống trùng
        existing_normalized = set()
        for item in existing_list:
            existing_normalized.add(normalize_text(item.get('question', '')))

        added_in_cat = 0
        for q in questions:
            norm = normalize_text(q['question'])
            if norm not in existing_normalized:
                existing_normalized.add(norm)
                q_entry = {
                    "category": cat_name,
                    "difficulty": q["difficulty"],
                    "question": q["question"],
                    "options": q["options"],
                    "correct": q["correct"],
                    "explanation": q["explanation"]
                }
                existing_list.append(q_entry)
                added_in_cat += 1
                total_added += 1

        with open(cat_file, 'w', encoding='utf-8') as f:
            json.dump(existing_list, f, ensure_ascii=False, indent=2)

        print(f"  📁 [{cat_name}]: Thêm mới {added_in_cat} câu hỏi -> Tổng danh mục: {len(existing_list)} câu.")

    conn.close()

    print("\n" + "=" * 70)
    print(f"✅ Đã thêm mới thành công {total_added} câu hỏi vào các tệp category JSON!")
    print("=" * 70)

if __name__ == '__main__':
    main()
